INSERT INTO repo_kprs (kpr_id, name, domain, discipline, principle_type, principle_granularity, definition, scope, core_ideas, semantic_description, keywords_synonyms, status) VALUES ('KPR_000109', 'Hall-Petch Relationship', 'Engineering & Technology', 'Engineering Materials', 'Constitutive Principle', 'Atomic', 'For many polycrystalline materials over applicable grain-size ranges, yield strength increases as grain size decreases according to an empirical inverse-square-root relation.', 'Applies over material and grain-size regimes where the empirical relationship is valid.', 'grain size; yield strength; grain boundaries', 'Provides an empirical structure-property relationship, not a universal law for all materials.', 'Hall Petch relation; grain size; yield strength; grain boundaries', 'Active'), ('KPR_000111', 'Newtonian Fluid Constitutive Principle', 'Engineering & Technology', 'Fluid Flow and Heat Transfer', 'Constitutive Principle', 'Atomic', 'For a Newtonian fluid, shear stress is proportional to shear rate through dynamic viscosity under the applicable conditions.', 'Applies to fluids behaving approximately Newtonian over the relevant shear-rate and temperature range.', 'shear stress; shear rate; viscosity', 'For a Newtonian fluid, shear stress is proportional to shear rate through dynamic viscosity under the applicable conditions. Its valid use is bounded by: Applies to fluids behaving approximately Newtonian over the relevant shear-rate and temperature range. Key ideas include shear stress; shear rate; viscosity.', 'Newtonian constitutive law; shear stress; shear rate; viscosity', 'Active'), ('KPR_000115', 'Closed-Loop Stability Principle', 'Engineering & Technology', 'Process Control and Instrumentation', 'Principle', 'Atomic', 'Closed-loop behaviour is governed by the poles or equivalent stability characteristics of the feedback system, so controller design must account for the plant, feedback path and controller together.', 'Applies to defined mathematical models and stability criteria; nonlinear and time-varying systems require appropriate analysis.', 'closed loop; poles; stability; feedback', 'Closed-loop behaviour is governed by the poles or equivalent stability characteristics of the feedback system, so controller design must account for the plant, feedback path and controller together. Its valid use is bounded by: Applies to defined mathematical models and stability criteria; nonlinear and time-varying systems require appropriate analysis. Key ideas include closed loop; poles; stability; feedback.', 'closed-loop stability; closed loop; poles; stability; feedback', 'Active'), ('KPR_000116', 'Internal Model Principle', 'Engineering & Technology', 'Process Control and Instrumentation', 'Principle', 'Atomic', 'Robust asymptotic rejection of a class of disturbances or tracking of reference signals requires the controller to contain an appropriate internal model of those signal dynamics.', 'Applies to specified signal classes and closed-loop regulation/tracking objectives.', 'internal model; disturbance rejection; tracking; robustness', 'Links controller structure to the dynamics of signals that must be tracked or rejected.', 'internal model principle; internal model; disturbance rejection; tracking; robustness', 'Active'), ('KPR_000117', 'Electromechanical Energy Conversion Principle', 'Engineering & Technology', 'Electrical Engineering', 'Principle', 'Atomic', 'Electromechanical devices exchange energy between electrical and mechanical domains through electromagnetic fields, with conversion governed by energy and co-energy relationships.', 'Applies to defined magnetic systems and appropriate energy/co-energy formulations.', 'magnetic field; electrical energy; mechanical energy; co-energy', 'Provides the energy basis for torque and force production in electrical machines.', 'electromechanical energy conversion; magnetic field; electrical energy; mechanical energy; co-energy', 'Active'), ('KPR_000119', 'Symmetrical Components Principle', 'Engineering & Technology', 'Power Systems', 'Principle', 'Atomic', 'An unbalanced three-phase set can be represented as the sum of positive-, negative- and zero-sequence balanced sets.', 'Applies to three-phase systems and phasor-domain analysis under the assumptions of symmetrical-component theory.', 'positive sequence; negative sequence; zero sequence; unbalance', 'An unbalanced three-phase set can be represented as the sum of positive-, negative- and zero-sequence balanced sets. Its valid use is bounded by: Applies to three-phase systems and phasor-domain analysis under the assumptions of symmetrical-component theory. Key ideas include positive sequence; negative sequence; zero sequence; unbalance.', 'symmetrical components; positive sequence; negative sequence; zero sequence; unbalance', 'Active'), ('KPR_000120', 'Power-Angle Stability Principle', 'Engineering & Technology', 'Power Systems', 'Principle', 'Atomic', 'The ability of synchronous machines to maintain synchronism depends on the relationship between electrical power transfer and rotor angle under the applicable network and machine model.', 'Applies to specified synchronous-machine and network models; stability assessment requires dynamic conditions and disturbance definition.', 'rotor angle; synchronism; transfer power; stability', 'The ability of synchronous machines to maintain synchronism depends on the relationship between electrical power transfer and rotor angle under the applicable network and machine model. Its valid use is bounded by: Applies to specified synchronous-machine and network models; stability assessment requires dynamic conditions and disturbance definition. Key ideas include rotor angle; synchronism; transfer power; stability.', 'power angle relationship; rotor angle; synchronism; transfer power; stability', 'Active'), ('KPR_000121', 'Volt-Second Balance Principle', 'Engineering & Technology', 'Power Electronics', 'Principle', 'Atomic', 'In steady periodic operation of an inductor, the average inductor voltage over one switching period is zero.', 'Applies to periodic steady-state converter operation where inductor flux does not drift.', 'inductor voltage; switching period; steady state; duty ratio', 'In steady periodic operation of an inductor, the average inductor voltage over one switching period is zero. Its valid use is bounded by: Applies to periodic steady-state converter operation where inductor flux does not drift. Key ideas include inductor voltage; switching period; steady state; duty ratio.', 'volt-second balance; inductor voltage; switching period; steady state; duty ratio', 'Active'), ('KPR_000122', 'Charge-Balance Principle', 'Engineering & Technology', 'Power Electronics', 'Principle', 'Atomic', 'In steady periodic operation of a capacitor, the average capacitor current over one switching period is zero.', 'Applies to periodic steady-state converter operation without net capacitor charge drift.', 'capacitor current; switching period; steady state', 'In steady periodic operation of a capacitor, the average capacitor current over one switching period is zero. Its valid use is bounded by: Applies to periodic steady-state converter operation without net capacitor charge drift. Key ideas include capacitor current; switching period; steady state.', 'charge balance; capacitor current; switching period; steady state', 'Active'), ('KPR_000123', 'Measurement Traceability Principle', 'Engineering & Technology', 'Electrical Engineering', 'Principle', 'Atomic', 'A measurement result is traceable when it can be related to a stated reference through an unbroken documented chain of calibrations, each contributing to measurement uncertainty.', 'Applies to measurement results with defined references, calibration chains and uncertainty contributions; traceability is not itself a statement of accuracy.', 'traceability; calibration chain; reference; uncertainty', 'A measurement result is traceable when it can be related to a stated reference through an unbroken documented chain of calibrations, each contributing to measurement uncertainty. Its valid use is bounded by: Applies to measurement results with defined references, calibration chains and uncertainty contributions; traceability is not itself a statement of accuracy. Key ideas include traceability; calibration chain; reference; uncertainty.', 'metrological traceability; traceability; calibration chain; reference; uncertainty', 'Active'), ('KPR_000124', 'Uncertainty Propagation Principle', 'Engineering & Technology', 'Electrical Engineering', 'Principle', 'Atomic', 'Uncertainty in a result derived from input quantities depends on the uncertainties and sensitivity coefficients of those inputs under the adopted measurement model.', 'Applies to defined measurement models and stated uncertainty evaluation methods.', 'uncertainty; sensitivity coefficient; measurement model; covariance', 'Uncertainty in a result derived from input quantities depends on the uncertainties and sensitivity coefficients of those inputs under the adopted measurement model. Its valid use is bounded by: Applies to defined measurement models and stated uncertainty evaluation methods. Key ideas include uncertainty; sensitivity coefficient; measurement model; covariance.', 'uncertainty propagation; uncertainty; sensitivity coefficient; measurement model; covariance', 'Active'), ('KPR_000125', 'Convolution Principle for LTI Systems', 'Engineering & Technology', 'Signals and Systems', 'Principle', 'Atomic', 'The output of a linear time-invariant system is the convolution of its input with the system''s impulse response.', 'Applies to LTI systems with appropriate mathematical conditions.', 'convolution; impulse response; LTI; system output', 'The output of a linear time-invariant system is the convolution of its input with the system''s impulse response. Its valid use is bounded by: Applies to LTI systems with appropriate mathematical conditions. Key ideas include convolution; impulse response; LTI; system output.', 'convolution property; convolution; impulse response; LTI; system output', 'Active'), ('KPR_000126', 'Fourier Decomposition Principle', 'Engineering & Technology', 'Signals and Systems', 'Principle', 'Atomic', 'Signals satisfying the relevant conditions can be represented in terms of sinusoidal or complex-exponential components whose amplitudes and phases describe spectral content.', 'Applies within the convergence and transform conditions of Fourier analysis.', 'frequency domain; spectrum; sinusoidal components; transform', 'Signals satisfying the relevant conditions can be represented in terms of sinusoidal or complex-exponential components whose amplitudes and phases describe spectral content. Its valid use is bounded by: Applies within the convergence and transform conditions of Fourier analysis. Key ideas include frequency domain; spectrum; sinusoidal components; transform.', 'Fourier principle; spectral decomposition', 'Active'), ('KPR_000127', 'Final-Value Theorem', 'Engineering & Technology', 'Signals and Systems', 'Theorem', 'Atomic', 'Under the stability and pole conditions required by the theorem, the final value of a time-domain signal can be obtained from the low-frequency behaviour of its Laplace transform.', 'Applies only when the required pole conditions hold; it cannot be used indiscriminately for unstable systems.', 'Laplace transform; final value; poles; stability', 'Under the stability and pole conditions required by the theorem, the final value of a time-domain signal can be obtained from the low-frequency behaviour of its Laplace transform. Its valid use is bounded by: Applies only when the required pole conditions hold; it cannot be used indiscriminately for unstable systems. Key ideas include Laplace transform; final value; poles; stability.', 'final value theorem; Laplace transform; final value; poles; stability', 'Active'), ('KPR_000128', 'Mitigation Hierarchy Principle', 'Law', 'Environmental Impact Assessment Law', 'Normative Principle', 'Atomic', 'Environmental decision-making should prioritize avoiding impacts, then minimizing them, restoring affected systems, and offsetting residual impacts where legally and scientifically appropriate.', 'Applies to impact-management decisions and should not be treated as permission to offset avoidable impacts.', 'avoid; minimize; restore; offset; residual impact', 'Environmental decision-making should prioritize avoiding impacts, then minimizing them, restoring affected systems, and offsetting residual impacts where legally and scientifically appropriate. Its valid use is bounded by: Applies to impact-management decisions and should not be treated as permission to offset avoidable impacts. Key ideas include avoid; minimize; restore; offset; residual impact.', 'mitigation hierarchy; avoid; minimize; restore; offset; residual impact', 'Active'), ('KPR_000129', 'Freedom of Contract Principle', 'Law', 'Contract Law and Commercial Agreements', 'Normative Principle', 'Atomic', 'Parties generally have autonomy to enter agreements and determine their terms within mandatory legal limits.', 'Applies subject to capacity, legality, public policy, consumer protection and other mandatory rules.', 'party autonomy; consent; contractual terms; mandatory law', 'Parties generally have autonomy to enter agreements and determine their terms within mandatory legal limits. Its valid use is bounded by: Applies subject to capacity, legality, public policy, consumer protection and other mandatory rules. Key ideas include party autonomy; consent; contractual terms; mandatory law.', 'freedom of contract; party autonomy', 'Active'), ('KPR_000130', 'Collective Bargaining Principle', 'Law', 'Labour and Employment Law', 'Normative Principle', 'Atomic', 'Workers and employers should be able to negotiate employment conditions collectively through recognized representative processes subject to applicable law.', 'Applies to collective labour relations and depends on statutory recognition and bargaining frameworks.', 'collective bargaining; representation; employment conditions', 'Workers and employers should be able to negotiate employment conditions collectively through recognized representative processes subject to applicable law. Its valid use is bounded by: Applies to collective labour relations and depends on statutory recognition and bargaining frameworks. Key ideas include collective bargaining; representation; employment conditions.', 'collective bargaining principle; collective bargaining; representation; employment conditions', 'Active'), ('KPR_000131', 'Equal Remuneration Principle', 'Law', 'Labour and Employment Law', 'Normative Principle', 'Atomic', 'Workers should receive equal remuneration for work of equal value without discrimination on grounds prohibited by applicable law.', 'Applies to comparable work/value assessment under the governing legal framework.', 'equal remuneration; discrimination; work of equal value', 'Workers should receive equal remuneration for work of equal value without discrimination on grounds prohibited by applicable law. Its valid use is bounded by: Applies to comparable work/value assessment under the governing legal framework. Key ideas include equal remuneration; discrimination; work of equal value.', 'equal pay principle; equal remuneration; discrimination; work of equal value', 'Active'), ('KPR_000132', 'Occupational Safety Prevention Principle', 'Law', 'Labour and Employment Law', 'Normative Principle', 'Atomic', 'Workplace risks should be identified and controlled through preventive measures before harm occurs, with responsibilities allocated across the occupational safety system.', 'Applies to workplace risk management and the applicable occupational safety regime.', 'hazard identification; risk control; prevention; worker protection', 'Frames workplace safety as preventive risk management rather than only post-incident response.', 'occupational safety prevention; hazard identification; risk control; prevention; worker protection', 'Active'), ('KPR_000133', 'Materiality Principle in Corporate Disclosure', 'Law', 'Corporate, Sustainability and ESG Law', 'Normative Principle', 'Atomic', 'Information is material when its omission, misstatement or obscuration could reasonably influence decisions of the intended users of the disclosure.', 'Applies to the relevant reporting framework and materiality definition; materiality thresholds depend on context.', 'materiality; disclosure; decision usefulness; reporting', 'Information is material when its omission, misstatement or obscuration could reasonably influence decisions of the intended users of the disclosure. Its valid use is bounded by: Applies to the relevant reporting framework and materiality definition; materiality thresholds depend on context. Key ideas include materiality; disclosure; decision usefulness; reporting.', 'materiality principle; materiality; disclosure; decision usefulness; reporting', 'Active'), ('KPR_000134', 'Thomas Theorem', 'Social Science', 'Sociology', 'Theorem', 'Atomic', 'When people define situations as real, those definitions can have real consequences for subsequent social action.', 'Applies as a sociological proposition about socially constructed meanings and consequences; it does not claim that subjective definitions alter physical facts.', 'definition of situation; social action; consequences', 'When people define situations as real, those definitions can have real consequences for subsequent social action. Its valid use is bounded by: Applies as a sociological proposition about socially constructed meanings and consequences; it does not claim that subjective definitions alter physical facts. Key ideas include definition of situation; social action; consequences.', 'Thomas theorem; definition of situation; social action; consequences', 'Unlinked'), ('KPR_000135', 'Self-Fulfilling Prophecy Principle', 'Social Science', 'Sociology', 'Principle', 'Atomic', 'An initially false or uncertain expectation can contribute to behaviours that make the expected outcome occur under suitable social conditions.', 'Applies to social interaction and institutional processes where expectations influence behaviour; it is not a universal causal law.', 'expectations; behaviour; feedback; social outcomes', 'An initially false or uncertain expectation can contribute to behaviours that make the expected outcome occur under suitable social conditions. Its valid use is bounded by: Applies to social interaction and institutional processes where expectations influence behaviour; it is not a universal causal law. Key ideas include expectations; behaviour; feedback; social outcomes.', 'self fulfilling prophecy; expectations; behaviour; feedback; social outcomes', 'Unlinked'), ('KPR_000136', 'Reflexivity Principle in Social Research', 'Social Science', 'Sociology', 'Methodological Principle', 'Atomic', 'Researchers should examine how their positions, assumptions, interactions and methodological choices may influence the production and interpretation of social knowledge.', 'Applies especially to qualitative and interpretive research; implementation varies by methodology.', 'researcher position; assumptions; interaction; interpretation', 'Researchers should examine how their positions, assumptions, interactions and methodological choices may influence the production and interpretation of social knowledge. Its valid use is bounded by: Applies especially to qualitative and interpretive research; implementation varies by methodology. Key ideas include researcher position; assumptions; interaction; interpretation.', 'reflexivity; researcher position; assumptions; interaction; interpretation', 'Active'), ('KPR_000137', 'Cognitive Dissonance Principle', 'Social Science', 'Social Psychology', 'Principle', 'Atomic', 'Inconsistent cognitions, attitudes or behaviour can create psychological tension that motivates processes aimed at reducing the inconsistency.', 'Applies to specified cognitive inconsistency conditions; magnitude and reduction strategies depend on context.', 'inconsistency; tension; attitude; behaviour; dissonance reduction', 'Inconsistent cognitions, attitudes or behaviour can create psychological tension that motivates processes aimed at reducing the inconsistency. Its valid use is bounded by: Applies to specified cognitive inconsistency conditions; magnitude and reduction strategies depend on context. Key ideas include inconsistency; tension; attitude; behaviour; dissonance reduction.', 'cognitive dissonance theory; inconsistency; tension; attitude; behaviour; dissonance reduction', 'Active'), ('KPR_000138', 'Social Identity Principle', 'Social Science', 'Social Psychology', 'Principle', 'Atomic', 'Part of social identity derives from perceived membership in social groups, and group categorization can influence self-concept, intergroup comparison and behaviour.', 'Applies to social categorization and identification processes rather than treating group membership as a complete explanation of behaviour.', 'social identity; categorization; group membership; comparison', 'Part of social identity derives from perceived membership in social groups, and group categorization can influence self-concept, intergroup comparison and behaviour. Its valid use is bounded by: Applies to social categorization and identification processes rather than treating group membership as a complete explanation of behaviour. Key ideas include social identity; categorization; group membership; comparison.', 'social identity theory; social identity; categorization; group membership; comparison', 'Active'), ('KPR_000139', 'Reciprocity Principle in Social Interaction', 'Social Science', 'Social Psychology', 'Normative Principle', 'Atomic', 'Social exchanges are often governed by expectations that benefits, assistance or obligations should be reciprocated within the relevant social context.', 'Applies to social-exchange settings and cultural contexts; it is not a universal moral rule.', 'reciprocity; social exchange; obligation; norms', 'Social exchanges are often governed by expectations that benefits, assistance or obligations should be reciprocated within the relevant social context. Its valid use is bounded by: Applies to social-exchange settings and cultural contexts; it is not a universal moral rule. Key ideas include reciprocity; social exchange; obligation; norms.', 'reciprocity principle; reciprocity; social exchange; obligation; norms', 'Active'), ('KPR_000140', 'Human Capital Investment Principle', 'Social Science', 'Development Economics', 'Principle', 'Atomic', 'Investment in education, skills and health can increase productive capabilities and future economic returns, subject to institutional and labour-market conditions.', 'Applies to human-capital accumulation and requires attention to quality, access, incentives and distribution.', 'human capital; education; skills; productivity; returns', 'Investment in education, skills and health can increase productive capabilities and future economic returns, subject to institutional and labour-market conditions. Its valid use is bounded by: Applies to human-capital accumulation and requires attention to quality, access, incentives and distribution. Key ideas include human capital; education; skills; productivity; returns.', 'human capital principle; human capital; education; skills; productivity; returns', 'Active'), ('KPR_000141', 'Subsidiarity Principle', 'Social Science', 'Public Policy and Governance', 'Normative Principle', 'Atomic', 'Public decisions should be taken at the lowest competent level capable of addressing the issue effectively, with higher levels acting where coordination or capacity requires.', 'Applies to multilevel governance arrangements and depends on constitutional/institutional allocation of powers.', 'subsidiarity; decentralization; competence; coordination', 'Public decisions should be taken at the lowest competent level capable of addressing the issue effectively, with higher levels acting where coordination or capacity requires. Its valid use is bounded by: Applies to multilevel governance arrangements and depends on constitutional/institutional allocation of powers. Key ideas include subsidiarity; decentralization; competence; coordination.', 'subsidiarity principle; subsidiarity; decentralization; competence; coordination', 'Active'), ('KPR_000142', 'Falsifiability Principle', 'Social Science', 'Research Methods in Social Sciences', 'Methodological Principle', 'Atomic', 'A scientific claim is methodologically stronger when it is formulated so that conceivable observations could count against it.', 'Applies to empirical claims that can be operationalized and tested; it does not imply that every useful scientific statement is immediately falsifiable.', 'testability; refutation; empirical claim; hypothesis', 'Provides a criterion for distinguishing testable empirical claims from claims insulated from evidence.', 'falsifiability; testability; refutation; empirical claim; hypothesis', 'Active'), ('KPR_000143', 'Triangulation Principle', 'Social Science', 'Research Methods in Social Sciences', 'Methodological Principle', 'Atomic', 'Confidence in an interpretation can be strengthened by examining a research question through multiple methods, data sources, investigators or theoretical perspectives where their assumptions are compatible.', 'Applies when the different evidence streams are genuinely relevant and their limitations are considered.', 'multiple methods; data sources; corroboration; convergence', 'Uses complementary evidence rather than treating repetition of the same method as independent confirmation.', 'methodological triangulation; multiple methods; data sources; corroboration; convergence', 'Active'), ('KPR_000144', 'Replication Principle', 'Social Science', 'Research Methods in Social Sciences', 'Methodological Principle', 'Atomic', 'A research finding gains evidential support when an independent study can reproduce the relevant result or pattern under the stated methods and conditions.', 'Applies to findings for which the design, data, procedures or conceptual target permit meaningful replication; replication need not produce identical numerical results.', 'replication; reproducibility; independent study; robustness', 'A research finding gains evidential support when an independent study can reproduce the relevant result or pattern under the stated methods and conditions. Its valid use is bounded by: Applies to findings for which the design, data, procedures or conceptual target permit meaningful replication; replication need not produce identical numerical results. Key ideas include replication; reproducibility; independent study; robustness.', 'replication principle; replication; reproducibility; independent study; robustness', 'Active'), ('KPR_000145', 'Bellman Optimality Principle', 'Engineering & Technology', 'Artificial Intelligence', 'Principle', 'Atomic', 'An optimal policy has the property that whatever the initial state and first decision, the remaining decisions must form an optimal policy for the resulting state.', 'Applies to sequential decision problems satisfying the dynamic-programming formulation and appropriate state representation.', 'optimal substructure; value function; dynamic programming; sequential decision', 'Provides the recursive basis for dynamic programming and many sequential decision algorithms.', 'Bellman optimality principle; optimal substructure', 'Active'), ('KPR_000146', 'PAC Learning Principle', 'Engineering & Technology', 'Machine Learning', 'Principle', 'Atomic', 'A hypothesis class is learnable in the PAC framework when a learning algorithm can, with high probability, produce a hypothesis whose error is below a specified tolerance using a sample size that is polynomially bounded in the relevant parameters.', 'Applies to the formal PAC model and its assumptions; it is a theoretical learnability framework rather than a guarantee for arbitrary deployed models.', 'probably approximately correct; sample complexity; hypothesis class; generalization', 'A hypothesis class is learnable in the PAC framework when a learning algorithm can, with high probability, produce a hypothesis whose error is below a specified tolerance using a sample size that is polynomially bounded in the relevant parameters. Its valid use is bounded by: Applies to the formal PAC model and its assumptions; it is a theoretical learnability framework rather than a guarantee for arbitrary deployed models. Key ideas include probably approximately correct; sample complexity; hypothesis class; generalization.', 'PAC learning; probably approximately correct; sample complexity; hypothesis class; generalization', 'Active'), ('KPR_000147', 'Quorum Intersection Principle', 'Engineering & Technology', 'Distributed Systems', 'Principle', 'Atomic', 'In quorum-based distributed protocols, sufficient overlap between read and write or decision quorums can ensure that operations observe or agree on shared state.', 'Applies to the quorum definitions and fault model of the specific protocol; quorum sizes alone do not guarantee correctness without protocol rules.', 'quorum; intersection; consistency; fault tolerance', 'In quorum-based distributed protocols, sufficient overlap between read and write or decision quorums can ensure that operations observe or agree on shared state. Its valid use is bounded by: Applies to the quorum definitions and fault model of the specific protocol; quorum sizes alone do not guarantee correctness without protocol rules. Key ideas include quorum; intersection; consistency; fault tolerance.', 'quorum intersection; quorum; intersection; consistency; fault tolerance', 'Active'), ('KPR_000148', 'Hess''s Law', 'Engineering & Technology', 'Chemical Engineering', 'Law', 'Atomic', 'The enthalpy change of an overall reaction equals the algebraic sum of enthalpy changes of a sequence of reactions connecting the same initial and final states.', 'Applies because enthalpy is a state function and requires consistent reaction definitions and conditions.', 'enthalpy; state function; reaction pathway; heat of reaction', 'The enthalpy change of an overall reaction equals the algebraic sum of enthalpy changes of a sequence of reactions connecting the same initial and final states. Its valid use is bounded by: Applies because enthalpy is a state function and requires consistent reaction definitions and conditions. Key ideas include enthalpy; state function; reaction pathway; heat of reaction.', 'Hess law; enthalpy; state function; reaction pathway; heat of reaction', 'Active'), ('KPR_000149', 'Raoult''s Law', 'Engineering & Technology', 'Mass Transfer Operations', 'Law', 'Atomic', 'For an ideal liquid solution, the partial pressure of a volatile component equals its liquid-phase mole fraction multiplied by its pure-component vapour pressure at the same temperature.', 'Applies to ideal or approximately ideal solutions and requires appropriate phase-equilibrium conditions.', 'vapour-liquid equilibrium; mole fraction; vapour pressure; ideal solution', 'For an ideal liquid solution, the partial pressure of a volatile component equals its liquid-phase mole fraction multiplied by its pure-component vapour pressure at the same temperature. Its valid use is bounded by: Applies to ideal or approximately ideal solutions and requires appropriate phase-equilibrium conditions. Key ideas include vapour-liquid equilibrium; mole fraction; vapour pressure; ideal solution.', 'Raoult law; vapour-liquid equilibrium; mole fraction; vapour pressure; ideal solution', 'Active'), ('KPR_000150', 'Henry''s Law', 'Engineering & Technology', 'Mass Transfer Operations', 'Law', 'Atomic', 'At dilute concentration and specified conditions, the equilibrium concentration or partial pressure of a dissolved gas is related to the gas-phase partial pressure through a Henry-law constant.', 'Applies to dilute systems and requires consistent convention for the Henry-law constant.', 'gas solubility; partial pressure; equilibrium; Henry constant', 'Provides an equilibrium relation widely used in gas absorption and environmental mass transfer.', 'Henry law; gas solubility; partial pressure; equilibrium; Henry constant', 'Active'), ('KPR_000151', 'Gibbs Phase Rule', 'Engineering & Technology', 'Chemical Engineering', 'Theorem', 'Atomic', 'For an equilibrium system, the number of independent intensive degrees of freedom is related to the number of components and phases through the Gibbs phase rule.', 'Applies to systems at thermodynamic equilibrium under the specified variables and component definitions.', 'degrees of freedom; phases; components; equilibrium', 'For an equilibrium system, the number of independent intensive degrees of freedom is related to the number of components and phases through the Gibbs phase rule. Its valid use is bounded by: Applies to systems at thermodynamic equilibrium under the specified variables and component definitions. Key ideas include degrees of freedom; phases; components; equilibrium.', 'Gibbs phase rule; degrees of freedom; phases; components; equilibrium', 'Active'), ('KPR_000152', 'Biot-Savart Law', 'Engineering & Technology', 'Electrical Engineering', 'Law', 'Atomic', 'The magnetic field contribution produced by a steady current element depends on current magnitude, geometry and distance according to the Biot-Savart relation.', 'Applies to magnetostatic conditions and the assumptions of the field formulation.', 'magnetic field; current element; distance; magnetostatics', 'Provides a fundamental field relation for calculating magnetic flux density from current distributions.', 'Biot Savart law; magnetic field; current element; distance; magnetostatics', 'Unlinked'), ('KPR_000153', 'Ampere''s Circuital Law', 'Engineering & Technology', 'Electrical Engineering', 'Law', 'Atomic', 'The circulation of the magnetic field around a closed path is related to enclosed current under the applicable magnetostatic or Maxwell-equation formulation.', 'Applies to specified current distributions and, in time-varying systems, requires the displacement-current term in the Maxwell-Ampere law.', 'magnetic field circulation; enclosed current; Maxwell equations', 'The circulation of the magnetic field around a closed path is related to enclosed current under the applicable magnetostatic or Maxwell-equation formulation. Its valid use is bounded by: Applies to specified current distributions and, in time-varying systems, requires the displacement-current term in the Maxwell-Ampere law. Key ideas include magnetic field circulation; enclosed current; Maxwell equations.', 'Ampere law; Maxwell Ampere law', 'Active'), ('KPR_000154', 'Gauss''s Law for Electricity', 'Engineering & Technology', 'Electrical Engineering', 'Law', 'Atomic', 'The electric flux through a closed surface equals the enclosed electric charge divided by the permittivity of free space in vacuum, with the corresponding material formulation in media.', 'Applies to electrostatic and Maxwell-equation formulations with appropriate treatment of materials.', 'electric flux; enclosed charge; electric field; permittivity', 'The electric flux through a closed surface equals the enclosed electric charge divided by the permittivity of free space in vacuum, with the corresponding material formulation in media. Its valid use is bounded by: Applies to electrostatic and Maxwell-equation formulations with appropriate treatment of materials. Key ideas include electric flux; enclosed charge; electric field; permittivity.', 'Gauss law; electric flux; enclosed charge; electric field; permittivity', 'Unlinked'), ('KPR_000155', 'Parseval''s Theorem', 'Engineering & Technology', 'Signals and Systems', 'Theorem', 'Atomic', 'Under the applicable energy and convergence conditions, the total signal energy can be represented equivalently in the time domain and frequency domain.', 'Applies to signals satisfying the required square-integrability or transform conditions.', 'signal energy; Fourier transform; time domain; frequency domain', 'Under the applicable energy and convergence conditions, the total signal energy can be represented equivalently in the time domain and frequency domain. Its valid use is bounded by: Applies to signals satisfying the required square-integrability or transform conditions. Key ideas include signal energy; Fourier transform; time domain; frequency domain.', 'Parseval theorem; signal energy; Fourier transform; time domain; frequency domain', 'Active'), ('KPR_000156', 'Central Limit Theorem', 'Social Science', 'Research Methods in Social Sciences', 'Theorem', 'Atomic', 'Under broad regularity conditions, appropriately normalized sums or sample means of independent observations converge in distribution toward a normal distribution as sample size increases.', 'Applies under stated assumptions and does not imply that every raw dataset is normally distributed.', 'sampling distribution; normal approximation; sample mean; convergence', 'Under broad regularity conditions, appropriately normalized sums or sample means of independent observations converge in distribution toward a normal distribution as sample size increases. Its valid use is bounded by: Applies under stated assumptions and does not imply that every raw dataset is normally distributed. Key ideas include sampling distribution; normal approximation; sample mean; convergence.', 'central limit theorem; sampling distribution; normal approximation; sample mean; convergence', 'Active'), ('KPR_000157', 'Law of Large Numbers', 'Social Science', 'Research Methods in Social Sciences', 'Law', 'Atomic', 'Under appropriate probabilistic conditions, sample averages converge toward their expected value as the number of observations increases.', 'Applies to specified stochastic assumptions and does not guarantee that any finite sample is close to the expectation.', 'sample mean; expectation; convergence; probability', 'Under appropriate probabilistic conditions, sample averages converge toward their expected value as the number of observations increases. Its valid use is bounded by: Applies to specified stochastic assumptions and does not guarantee that any finite sample is close to the expectation. Key ideas include sample mean; expectation; convergence; probability.', 'law of large numbers; sample mean; expectation; convergence; probability', 'Active'), ('KPR_000158', 'Moment-Area Theorem', 'Engineering & Technology', 'Civil Engineering', 'Theorem', 'Atomic', 'Beam slopes and deflections can be related to the area and first moment of area of the bending-moment diagram divided by flexural rigidity under the assumptions of elastic beam theory.', 'Applies to beams satisfying the assumptions of the moment-area method, including the relevant beam theory, loading and material conditions.', 'curvature; M/EI; area-moment; slope; deflection', 'Provides a graphical/integral relationship between beam curvature and changes in slope and deflection.', 'moment-area method; moment-area theorem; beam deflection', 'Active'), ('KPR_000159', 'Grashof''s Criterion', 'Engineering & Technology', 'Mechanical Engineering', 'Criterion', 'Atomic', 'For a planar four-bar linkage, the shortest and longest link lengths relative to the other two determine whether at least one link can make a complete rotation under the Grashof condition.', 'Applies to planar four-bar mechanisms and the link-length criterion; joint limits, interference and practical transmission effects require additional analysis.', 'link lengths; four-bar linkage; rotation; mobility', 'Provides a kinematic criterion for classifying possible full-rotation behaviour of four-bar mechanisms.', 'Grashof criterion; Grashof law', 'Active') ON CONFLICT DO NOTHING;